var ITEMS=[["What appliance techs do","Appliance repair technicians diagnose and fix washers, dryers, refrigerators, ovens, and dishwashers in homes. It is electrical plus mechanical plus customer service \u2014 and every home has a waiting customer base."], ["Essential tools","Multimeter, clamp meter, nut driver set, screwdrivers, pliers, putty knife, appliance dolly, work gloves, flashlight, and a parts organizer. Pros add: megohmmeter, manometer, and manufacturer service manuals."], ["Key skills","Systematic diagnosis: verify the complaint, isolate the system, test components. Reading wiring diagrams and tech sheets. Sealed-system basics for refrigeration. Gas safety for ranges and dryers. Explaining repairs clear"], ["Safety essentials","Unplug before opening \u2014 and verify. Capacitors hold charge: discharge them. Gas: leak-check every connection with solution. Refrigerant: EPA rules apply. Water plus electricity: respect both."], ["Getting started","Start with manufacturer training or trade school; many learn as helpers. Get EPA 608 for refrigeration work. Build a van stock of common parts. Flat-rate pricing and clear communication build the business."], ["Pro tips","Always verify the complaint first \u2014 half of no-cools are settings or breakers. Check the simple things: filters, vents, water supply. Document model numbers with photos. Stock common igniters, thermostats, and belts."], ["Tech sheet","Trade term \u2014 Tech sheet: The wiring diagram hidden in the appliance."], ["Error code","Trade term \u2014 Error code: The appliance's self-diagnosis display."], ["Sealed system","Trade term \u2014 Sealed system: The refrigerant circuit: compressor, condenser, evaporator."], ["Compressor","Trade term \u2014 Compressor: The refrigerant pump."], ["Start relay","Trade term \u2014 Start relay: The component starting the compressor."], ["Defrost system","Trade term \u2014 Defrost system: Heater, thermostat, and timer preventing frost buildup."], ["Igniter","Trade term \u2014 Igniter: The glowing part lighting gas ovens and dryers."], ["Thermal fuse","Trade term \u2014 Thermal fuse: One-time safety fuse in dryers."], ["Drive belt","Trade term \u2014 Drive belt: Transfers motor power in washers and dryers."], ["Agitator","Trade term \u2014 Agitator: The washer's washing motion part."], ["Suspension rods","Trade term \u2014 Suspension rods: Washer tub stabilizers."], ["Drain pump","Trade term \u2014 Drain pump: Pumps washer water out."], ["Inlet valve","Trade term \u2014 Inlet valve: Controls water into washers and dishwashers."], ["Heating element","Trade term \u2014 Heating element: Electric heat for dryers and ovens."], ["Thermostat","Trade term \u2014 Thermostat: Temperature control and safety."], ["Control board","Trade term \u2014 Control board: The electronic brain."], ["Megohmmeter","Trade term \u2014 Megohmmeter: Tests motor and compressor insulation."], ["Manometer","Trade term \u2014 Manometer: Measures gas pressure."], ["Flat rate","Trade term \u2014 Flat rate: Fixed pricing per job type."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
